        $rows = [
            ['id' => 1,  'codigo' => 'OPS-PATS-001', 'id_misional' => '1HEXPATS', 'id_modelo' => '1hexpats1', 'proceso' => 'Solicitud de Información de Usuario PATS', 'fase' => 'Atención inicial e identificación de necesidades', 'tipo_caso' => 'RECEPCION_INICIAL', 'subtipo_caso' => 'Clasificación de duda', 'pregunta_operativa' => '¿Qué debe hacer Concierge cuando un usuario PATS llega con una duda general?', 'situacion_usuario' => 'El usuario llega al módulo o canal autorizado y pregunta por beneficios, precios, uso de app, vigencia, red, servicios, descuentos o cotizaciones.', 'respuesta_usuario_sugerida' => 'Claro, con gusto te ayudo. Primero voy a identificar si tu duda es sobre beneficios, precios, una cotización, tu vigencia o el uso de tu PATS para orientarte correctamente.', 'pasos_operativos' => "1. Recibir al usuario con saludo cordial.\n2. Escuchar la duda completa sin interrumpir.\n3. Clasificar la solicitud: información general, precio/descuento, cotización, búsqueda individual, vigencia, uso de app o derivación.\n4. Solicitar nombre completo o ID PATS solo si la duda requiere búsqueda individual.\n5. Explicar al usuario cuál será la ruta de atención: PATS DROP, PATS MONEY, LEAD+, PATS Vigencias o derivación.", 'validaciones' => 'Solicitar datos personales solo cuando sean necesarios. No validar vigencia si la duda es meramente informativa. Confirmar si la persona es usuario PATS o no usuario.', 'modulos_consultar' => 'PATS DROP, PATS MONEY, LEAD+, PATS Vigencias', 'cuando_escalar' => 'Escalar si el usuario solicita una excepción, si hay inconsistencia de información, si la plataforma no muestra el dato o si el caso requiere autorización de ADMINPATS.', 'frases_sugeridas' => '"Te ayudo a ubicar la información correcta." | "Para esta duda sí necesito validar tu ID PATS." | "Esta información la revisaré en la sección correspondiente para no darte un dato incorrecto."', 'errores_evitar' => 'No pedir ID PATS si no es necesario. No prometer cobertura. No improvisar precios. No decir que todo está incluido.', 'roles_aplica' => 'CON,CONCIERGE,ADM,ADMISION,ADMIN,ADMINPATS', 'nivel' => 'OPERATIVO', 'prioridad' => 100, 'keywords' => 'usuario llega duda informacion beneficios precios vigencia red servicios descuentos cotizacion modulo concierge admision clasificar solicitud', 'fuente' => 'PROCESOS_OPERATIVOS_PATS', 'activo' => 1, 'created_at' => '2026-04-24 07:53:31', 'updated_at' => '2026-04-24 07:53:31'],
            ['id' => 2,  'codigo' => 'OPS-PATS-002', 'id_misional' => '1HEXPATS', 'id_modelo' => '1hexpats2', 'proceso' => 'Solicitud de Información de Usuario PATS', 'fase' => 'Servicios y Beneficios', 'tipo_caso' => 'INFORMACION_GENERAL', 'subtipo_caso' => 'Consulta en PATS DROP', 'pregunta_operativa' => '¿Qué hago si el usuario pregunta qué incluye PATS?', 'situacion_usuario' => 'El usuario pregunta: "¿Qué incluye mi PATS?", "¿Qué beneficios tengo?", "¿Me enseñas el brochure?" o "¿Qué servicios puedo usar?".', 'respuesta_usuario_sugerida' => 'Tu PATS te permite acceder a beneficios dentro de la red autorizada. Algunas consultas pueden ser sin costo, como medicina general y urgencias, y otros servicios pueden tener precio preferencial o descuento. Voy a revisar la información vigente para explicártelo correctamente.', 'pasos_operativos' => "1. Ingresar a PATS DROP.\n2. Localizar brochure, beneficios o documento vigente.\n3. Explicar la información en lenguaje claro.\n4. Aclarar diferencia entre servicios sin costo y servicios con precio preferencial.\n5. Confirmar que el usuario entendió.\n6. Documentar resultado si el flujo lo requiere.", 'validaciones' => 'Confirmar que la información consultada sea vigente. Si se habla de un servicio específico, validar si requiere red, tabulador o condiciones especiales.', 'modulos_consultar' => 'PATS DROP', 'cuando_escalar' => 'Escalar si el beneficio no aparece, si el usuario cuestiona una diferencia contra lo prometido o si la información del brochure está desactualizada.', 'frases_sugeridas' => '"Te explico la diferencia: algunos servicios son sin costo y otros tienen precio preferencial." | "Antes de confirmarte un servicio específico, reviso que esté en la información vigente."', 'errores_evitar' => 'No decir que PATS es seguro. No decir "te cubre todo". No decir que un servicio es gratis si solo tiene precio preferencial.', 'roles_aplica' => 'CON,CONCIERGE,ADM,ADMISION,ADMIN,ADMINPATS', 'nivel' => 'OPERATIVO', 'prioridad' => 98, 'keywords' => 'que incluye pats beneficios brochure pats drop servicios sin costo precio preferencial usuario pregunta', 'fuente' => 'PROCESOS_OPERATIVOS_PATS', 'activo' => 1, 'created_at' => '2026-04-24 07:53:31', 'updated_at' => '2026-04-24 07:53:31'],
            ['id' => 3,  'codigo' => 'OPS-PATS-003', 'id_misional' => '1HEXPATS', 'id_modelo' => '1hexpats3', 'proceso' => 'Solicitud de Información de Usuario PATS', 'fase' => 'Precios y Descuentos', 'tipo_caso' => 'PRECIOS_DESCUENTOS', 'subtipo_caso' => 'Consulta en PATS MONEY', 'pregunta_operativa' => '¿Qué hago si el usuario pregunta cuánto cuesta un estudio, servicio o procedimiento?', 'situacion_usuario' => 'El usuario pregunta: "¿Cuánto cuesta este estudio?", "¿Qué descuento tengo?", "¿Cuánto pagaría con mi PATS?" o "¿Cuál es el precio PATS?".', 'respuesta_usuario_sugerida' => 'Voy a revisar el precio vigente en la plataforma para darte el valor correcto. Si aparece en sistema, te explicaré el precio normal y el precio o beneficio como usuario PATS.', 'pasos_operativos' => "1. Ingresar a PATS MONEY.\n2. Buscar el estudio, servicio o concepto.\n3. Identificar precio general y precio/beneficio PATS.\n4. Explicar si se trata de descuento, precio preferencial o beneficio específico.\n5. Confirmar si el usuario desea consultar otro servicio.\n6. Si no aparece o falla la plataforma, definir seguimiento.", 'validaciones' => 'Validar que el servicio esté dentro de red autorizada. Validar si el precio corresponde a hospital, laboratorio, imagenología, farmacia o especialista. Confirmar tabulador vigente antes de informar monto.', 'modulos_consultar' => 'PATS MONEY', 'cuando_escalar' => 'Escalar si el precio no aparece, si hay diferencia contra un tabulador impreso, si el usuario reclama cobro diferente o si se trata de paquete/cotización quirúrgica.', 'frases_sugeridas' => '"Te muestro el precio normal y el precio como usuario PATS." | "Este dato depende del tabulador vigente, por eso lo estoy validando en plataforma."', 'errores_evitar' => 'No inventar precios. No usar precios de memoria. No asegurar que el precio es final si puede haber insumos, medicamentos, honorarios o servicios adicionales.', 'roles_aplica' => 'CON,CONCIERGE,ADM,ADMISION,CAJ,CAJA,ADMIN,ADMINPATS', 'nivel' => 'CRITICO', 'prioridad' => 100, 'keywords' => 'precio descuento costo estudio pats money cuanto cuesta valor normal beneficio pats tabulador', 'fuente' => 'PROCESOS_OPERATIVOS_PATS', 'activo' => 1, 'created_at' => '2026-04-24 07:53:31', 'updated_at' => '2026-04-24 07:53:31'],
            ['id' => 4,  'codigo' => 'OPS-PATS-004', 'id_misional' => '1HEXPATS', 'id_modelo' => '1hexpats3', 'proceso' => 'Solicitud de Información de Usuario PATS', 'fase' => 'Precios y Descuentos', 'tipo_caso' => 'CONTINGENCIA_PRECIO', 'subtipo_caso' => 'Falla de PATS MONEY', 'pregunta_operativa' => '¿Qué hago si PATS MONEY no funciona o no me deja consultar precios?', 'situacion_usuario' => 'El usuario solicita un precio, pero la plataforma PATS MONEY está fallando, lenta, sin conexión o no permite consultar el servicio.', 'respuesta_usuario_sugerida' => 'En este momento no puedo confirmar el precio en plataforma. Para no darte un dato incorrecto, voy a dejar tu solicitud con seguimiento o canalizarla para validación del precio vigente.', 'pasos_operativos' => "1. Informar la contingencia sin culpar al sistema.\n2. No improvisar precio.\n3. Tomar datos de contacto si se requiere seguimiento.\n4. Registrar servicio solicitado.\n5. Canalizar a ADMINPATS, área comercial o responsable definido.\n6. Dar siguiente paso claro al usuario.", 'validaciones' => 'Confirmar nombre, teléfono, servicio solicitado y unidad. Si el usuario está en caja o admisión, evitar cobro hasta validar precio cuando exista duda.', 'modulos_consultar' => 'PATS MONEY, PATS Concierge', 'cuando_escalar' => 'Escalar a ADMINPATS o responsable de tabulador si el usuario requiere atención inmediata o si el precio es indispensable para continuar.', 'frases_sugeridas' => '"Prefiero validarlo antes de darte un monto incorrecto." | "Te dejamos seguimiento para confirmarte el precio vigente."', 'errores_evitar' => 'No decir "no sé". No dejar al usuario sin siguiente paso. No cobrar con un precio no validado.', 'roles_aplica' => 'CON,CONCIERGE,ADM,ADMISION,CAJ,CAJA,ADMIN,ADMINPATS', 'nivel' => 'CRITICO', 'prioridad' => 96, 'keywords' => 'falla pats money no funciona precio no disponible contingencia tabulador seguimiento precio', 'fuente' => 'PROCESOS_OPERATIVOS_PATS', 'activo' => 1, 'created_at' => '2026-04-24 07:53:31', 'updated_at' => '2026-04-24 07:53:31'],
            ['id' => 5,  'codigo' => 'OPS-PATS-005', 'id_misional' => '1HEXPATS', 'id_modelo' => '1hexpats4', 'proceso' => 'Solicitud de Información de Usuario PATS', 'fase' => 'Paquetes y Cotizaciones', 'tipo_caso' => 'COTIZACION', 'subtipo_caso' => 'Búsqueda en LEAD+', 'pregunta_operativa' => '¿Qué hago si el usuario quiere cotizar una cirugía o procedimiento?', 'situacion_usuario' => 'El usuario dice: "Quiero cotizar una cirugía", "¿Cuánto cuesta este procedimiento con PATS?" o "¿Cuánto pagaría yo?".', 'respuesta_usuario_sugerida' => 'Voy a revisar si el procedimiento ya está disponible para cotización. Si aparece, te explicaré el valor general y el valor como usuario PATS. Si no aparece, tomaremos tus datos para gestionar la cotización.', 'pasos_operativos' => "1. Clasificar la solicitud como cotización.\n2. Ingresar a LEAD+.\n3. Buscar el procedimiento solicitado.\n4. Si aparece, mostrar y explicar valor general y valor PATS.\n5. Aclarar alcance de la cotización.\n6. Si no aparece, tomar datos de contacto.\n7. Solicitar al área comercial preparar la cotización.\n8. Registrar seguimiento.", 'validaciones' => 'Confirmar procedimiento exacto, unidad, datos de contacto, si requiere especialista, si es cirugía/procedimiento y si el valor incluye o no honorarios, insumos o condiciones adicionales.', 'modulos_consultar' => 'LEAD+, PATS MONEY, PATS Concierge', 'cuando_escalar' => 'Escalar a área comercial del hospital o ADMINPATS si el procedimiento no aparece, si el monto no está autorizado o si requiere armado de paquete.', 'frases_sugeridas' => '"Esta solicitud entra como cotización." | "Voy a buscar el procedimiento en LEAD+." | "Si no está visible, dejamos seguimiento para prepararlo correctamente."', 'errores_evitar' => 'No prometer precio final sin validar alcance. No decir que la cirugía está cubierta como seguro. No confirmar disponibilidad médica si no está validada.', 'roles_aplica' => 'CON,CONCIERGE,ADM,ADMISION,ADMIN,ADMINPATS', 'nivel' => 'CRITICO', 'prioridad' => 100, 'keywords' => 'cotizar cirugia procedimiento quirurgico lead+ lead precio paquete cotizacion usuario pats', 'fuente' => 'PROCESOS_OPERATIVOS_PATS', 'activo' => 1, 'created_at' => '2026-04-24 07:53:31', 'updated_at' => '2026-04-24 07:53:31'],
            ['id' => 6,  'codigo' => 'OPS-PATS-006', 'id_misional' => '1HEXPATS', 'id_modelo' => '1hexpats4', 'proceso' => 'Solicitud de Información de Usuario PATS', 'fase' => 'Paquetes y Cotizaciones', 'tipo_caso' => 'COTIZACION_NO_VISIBLE', 'subtipo_caso' => 'Procedimiento no aparece en LEAD+', 'pregunta_operativa' => '¿Qué hago si el procedimiento que pide el usuario no aparece en LEAD+?', 'situacion_usuario' => 'El usuario solicita una cotización de cirugía/procedimiento, pero el procedimiento no está visible en LEAD+.', 'respuesta_usuario_sugerida' => 'En este momento ese procedimiento no aparece visible en plataforma. Tomaré tus datos para solicitar la cotización al área correspondiente y darte seguimiento por el medio que nos indiques.', 'pasos_operativos' => "1. Informar que no está visible sin descartar el servicio.\n2. Tomar nombre, teléfono, correo, procedimiento solicitado y unidad.\n3. Registrar solicitud.\n4. Enviar solicitud al área comercial/responsable.\n5. Validar cuando la cotización se active en LEAD+.\n6. Contactar al usuario con el resultado.", 'validaciones' => 'Validar que el dato de contacto sea correcto. Confirmar procedimiento con el usuario. Registrar medio preferido de contacto. No asumir precios aproximados.', 'modulos_consultar' => 'LEAD+, PATS Concierge', 'cuando_escalar' => 'Escalar a área comercial o ADMINPATS. Si el usuario requiere atención inmediata, canalizar a admisión o responsable médico-operativo según el caso.', 'frases_sugeridas' => '"No quiero darte un monto incompleto; lo gestionamos y te contactamos." | "Voy a dejar la solicitud registrada para seguimiento."', 'errores_evitar' => 'No decir que no existe definitivamente. No prometer en automático que se autorizará.', 'roles_aplica' => 'CON,CONCIERGE,ADM,ADMISION,ADMIN,ADMINPATS', 'nivel' => 'CRITICO', 'prioridad' => 98, 'keywords' => 'procedimiento no aparece lead+ no visible cotizacion pendiente solicitar comercial seguimiento datos contacto', 'fuente' => 'PROCESOS_OPERATIVOS_PATS', 'activo' => 1, 'created_at' => '2026-04-24 07:53:31', 'updated_at' => '2026-04-24 07:53:31'],
            ['id' => 7,  'codigo' => 'OPS-PATS-007', 'id_misional' => '1HEXPATS', 'id_modelo' => '1hexpats5', 'proceso' => 'Solicitud de Información de Usuario PATS', 'fase' => 'Derivación', 'tipo_caso' => 'DERIVACION_GENERAL', 'subtipo_caso' => 'Usuario necesita saber a dónde ir o con quién continuar', 'pregunta_operativa' => '¿Qué hago si después de la orientación el usuario pregunta a dónde debe ir?', 'situacion_usuario' => 'El usuario dice: "Entonces, ¿a dónde tengo que ir?", "¿Con quién sigo?", "¿Me puedes ayudar con la app?" o "¿Cuál es el siguiente paso?".', 'respuesta_usuario_sugerida' => 'El siguiente paso depende del tipo de servicio. Te voy a indicar si debes pasar a admisión, caja, consulta, laboratorio, imagenología, farmacia, urgencias o si debemos dejar seguimiento.', 'pasos_operativos' => "1. Identificar necesidad complementaria.\n2. Determinar si requiere unidad, especialista, app, admisión, caja o seguimiento.\n3. Explicar ruta en lenguaje sencillo.\n4. Confirmar que el usuario entendió.\n5. Registrar derivación cuando aplique.", 'validaciones' => 'Validar si el usuario requiere cita, pago, estatus activo, QR, identificación o referencia antes de dirigirlo al área.', 'modulos_consultar' => 'PATS Concierge, directorio interno, PATS DROP', 'cuando_escalar' => 'Escalar si el usuario requiere excepción, acceso sin estatus válido, queja, problema de pago o soporte técnico no resoluble en módulo.', 'frases_sugeridas' => '"Te explico el siguiente paso para que no tengas que dar vueltas." | "Primero pasas a ___ y después continúas en ___."', 'errores_evitar' => 'No mandar al usuario de un área a otra sin confirmar el paso. No derivar a servicio no autorizado.', 'roles_aplica' => 'CON,CONCIERGE,ADM,ADMISION,ADMIN,ADMINPATS', 'nivel' => 'OPERATIVO', 'prioridad' => 92, 'keywords' => 'derivacion a donde ir siguiente paso admision caja laboratorio imagenologia farmacia urgencias app', 'fuente' => 'PROCESOS_OPERATIVOS_PATS', 'activo' => 1, 'created_at' => '2026-